
window.VSim=window.VSim||{};(function(NS){
class Telemetry{
 constructor(d=null){this.sessionId=d?.sessionId||('session-'+new Date().toISOString().replace(/[:.]/g,'-'));this.entries=d?.entries||[];this.snapshots=d?.snapshots||[];}
 record(type,w,payload={}){this.entries.push({id:this.entries.length+1,realTime:new Date().toISOString(),simTime:w.timestamp(),ordinalDay:w.ordinalDay(),type,payload});if(this.entries.length>14000)this.entries.shift();}
 snapshot(w,reason='AUTO',note=''){const villages=w.villages.map(v=>{const d=v.demographics(),rr=v.resourceRatios(w),tech=v.researchTarget?NS.TECH[v.researchTarget]:null;return{id:v.id,name:v.name,status:v.status,brain:v.brain.label,population:v.population(),avgHealth:+v.avgHealth().toFixed(2),avgHappiness:+v.avgHappiness().toFixed(2),avgEnergy:+v.avgEnergy().toFixed(2),avgHunger:+v.avgHunger().toFixed(2),food:+v.food.toFixed(2),foodReserveDays:+v.foodReserveDays().toFixed(2),wood:+v.wood.toFixed(2),stone:+v.stone.toFixed(2),gold:+v.gold.toFixed(2),foodStorage:+v.storageCaps(w).food.toFixed(1),woodStorage:+v.storageCaps(w).wood.toFixed(1),stoneStorage:+v.storageCaps(w).stone.toFixed(1),security:v.status==='active'?v.securityScore(w):0,threat:+v.threat.toFixed(2),focus:v.focus,territoryTiles:v.territory.size,occupiedTiles:v.occupiedTerritoryCount(w),resourceFoodRatio:+rr.food.toFixed(3),resourceWoodRatio:+rr.wood.toFixed(3),resourceStoneRatio:+rr.stone.toFixed(3),resourceGoldRatio:+rr.gold.toFixed(3),expansionTarget:v.expansionProject?.targetTileId??null,expansionProgress:v.expansionProject?v.expansionProject.progress/v.expansionProject.duration:null,age0_14:d.child,age15_17:d.teen,age18_42:d.adult,age43_64:d.middle,age65plus:d.elder,reproductiveWomen:d.reproductiveWomen,reproductiveMen:d.reproductiveMen,technologyCount:v.technologies.size,technologies:[...v.technologies].join('|'),researchTarget:v.researchTarget||'',researchLabel:tech?.label||'',researchProgress:+v.researchProgress.toFixed(2),researchCost:tech?.cost||0,totalKnowledge:+v.totalKnowledge.toFixed(2),tradeCount:v.tradeStats.count,tradeImports:+v.tradeStats.imports.toFixed(2),tradeExports:+v.tradeStats.exports.toFixed(2),tradeGoldSpent:+v.tradeStats.goldSpent.toFixed(2),tradeGoldEarned:+v.tradeStats.goldEarned.toFixed(2),internalMigrations:v.migrationStats.internal,externalIn:v.migrationStats.externalIn,externalOut:v.migrationStats.externalOut};});const s={realTime:new Date().toISOString(),simTime:w.timestamp(),ordinalDay:w.ordinalDay(),reason,note,global:{population:w.allPeople.length,activeVillages:w.activeVillages.length,ruins:w.ruinCount(),territoryTiles:w.map.tiles.filter(t=>t.ownerId!==null).length,totalGold:+w.activeVillages.reduce((a,v)=>a+v.gold,0).toFixed(2),avgHealth:+w.averageStat('health').toFixed(2),avgHappiness:+w.averageStat('happiness').toFixed(2),tradeCount:w.activeVillages.reduce((a,v)=>a+v.tradeStats.count,0)/2,totalKnowledge:+w.activeVillages.reduce((a,v)=>a+v.totalKnowledge,0).toFixed(2)},villages};this.snapshots.push(s);if(this.snapshots.length>4000)this.snapshots.shift();return s;}
 manualCapture(w,note){const s=this.snapshot(w,'MANUAL',note||'');this.record('MANUAL_NOTE',w,{note:note||'',snapshotOrdinalDay:s.ordinalDay});return s;}
 toJSON(w){return{format:'village-observer-devlog',version:'0.6',exportedAt:new Date().toISOString(),sessionId:this.sessionId,worldSummary:{simTime:w.timestamp(),map:{width:w.map.width,height:w.map.height},eventCount:w.eventCount,activeVillages:w.activeVillages.length,ruins:w.ruinCount(),recentTrades:w.recentTrades.length,settlementEconomy:true},entries:this.entries,snapshots:this.snapshots};}
 snapshotsCSV(){const c=['simTime','ordinalDay','reason','note','village','status','brain','population','avgHealth','avgHappiness','avgEnergy','avgHunger','food','foodReserveDays','wood','stone','gold','foodStorage','woodStorage','stoneStorage','security','threat','focus','territoryTiles','occupiedTiles','resourceFoodRatio','resourceWoodRatio','resourceStoneRatio','resourceGoldRatio','expansionTarget','expansionProgress','age0_14','age15_17','age18_42','age43_64','age65plus','reproductiveWomen','reproductiveMen','technologyCount','technologies','researchTarget','researchLabel','researchProgress','researchCost','totalKnowledge','tradeCount','tradeImports','tradeExports','tradeGoldSpent','tradeGoldEarned','internalMigrations','externalIn','externalOut'],esc=v=>`"${String(v??'').replace(/"/g,'""')}"`;const rows=[c.map(esc).join(',')];for(const s of this.snapshots)for(const v of s.villages)rows.push(c.map(k=>esc(v[k]??(k==='simTime'?s.simTime:k==='ordinalDay'?s.ordinalDay:k==='reason'?s.reason:k==='note'?s.note:''))).join(','));return rows.join('\n');}
 serialize(){return{sessionId:this.sessionId,entries:this.entries,snapshots:this.snapshots};}
}
NS.Telemetry=Telemetry;
})(window.VSim);

